def wav(path):
 raw=path.read_bytes();pos=12
 while pos+8<=len(raw):
  kind,length=struct.unpack_from('<4sI',raw,pos);pos+=8
  if kind==b'data':return np.frombuffer(raw[pos:pos+length],dtype='<f4').reshape(-1,2).astype(float)
  pos+=length+(length&1)
 raise RuntimeError('missing data')
def db(x):return 20*np.log10(max(float(x),1e-12))
def rms(x):return np.sqrt(np.mean(x*x))
def band(x,freq,width=4):
 a=x.mean(axis=1);a=a-a.mean();n=len(a);s=np.fft.rfft(a*np.hanning(n));f=np.fft.rfftfreq(n,1/48000)
 return float(np.sum(np.abs(s[(f>=freq-width)&(f<=freq+width)])**2))
def ratio(a,b):return 10*np.log10(max(a,1e-24)/max(b,1e-24))
def window(a,start,end):return a[round(start*48000):round(end*48000)]
